void scsi_abort_complete(struct scsi_cmnd *cmd) {
    struct Scsi_Host *shost = cmd->device->host;

    if (!cmd || !shost) {
        return;
    }

    spin_lock_irq(shost->host_lock);

    if (cmd->state == SCSI_CMD_ABORTED) {
        scsi_finish_command(cmd);
        scsi_remove_from_error_queue(cmd);
        scsi_add_to_error_handler_queue(cmd);
    }

    spin_unlock_irq(shost->host_lock);
}
